def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def safe_xy(obj, default=(0, 0)):
        try:
            if isinstance(obj, (list, tuple)) and len(obj) >= 2:
                return int(obj[0]), int(obj[1])
        except:
            pass
        return default

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_point(points, origin, mode="min"):
        best = None
        best_score = None
        for p in points:
            x, y = safe_xy(p, None)
            if x is None:
                continue
            s = manhattan(origin, (x, y))
            if best is None or (mode == "min" and s < best_score) or (mode == "max" and s > best_score):
                best = (x, y)
                best_score = s
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_xy(observation.get("self_position", (0, 0)))
    ox, oy = safe_xy(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_point(corners, opp_pos, mode="max")
        if target is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_point(targets, self_pos, mode="min")
        if target is not None:
            return step_toward(self_pos, target)
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        center = (max(0, w // 2), max(0, h // 2))
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("resource_positions") or []
    target = best_point(resources, self_pos, mode="min")
    if target is not None:
        return step_toward(self_pos, target)

    # Denial / fallback behavior: if no resource visible, bias toward opponent or center.
    if ox != sx or oy != sy:
        return step_toward(self_pos, opp_pos)

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    center = (max(0, w // 2), max(0, h // 2))
    return step_toward(self_pos, center)

